// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type DashboardCardRevealProps = Record<string, any>;

// Helper for leading zeros
const pad = (num: number) => (num < 10 ? `0${num}` : num.toString());

const DashboardCardReveal: React.FC<DashboardCardRevealProps> = ({
  backgroundColor = "#2A2A2D",
  transparentBackground = false,
  durationInSeconds = 15,
  cardColor = "rgba(25, 25, 25, 0.4)", // Adjusted slightly for better glass transparency
  accentColor = "#E4B873",
  textColor = "#F5F5F5",
  subTextColor = "#888888",
  mainTitle = "The 5 Topics that come up the most",
  topics = [
    "Algebra & Equations",
    "Geometry & Shapes",
    "Trigonometry Rules",
    "Probability & Stats",
    "Calculus Basics"
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background Logic
  const bgStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: "transparent" }
    : {
        background: `radial-gradient(circle at 50% 30%, ${backgroundColor} 0%, #050505 100%)`,
        backgroundColor: "#050505",
      };

  const totalFrames = durationInSeconds * fps;
  
  // Timeline Calculations
  const introDuration = Math.min(fps * 3, Math.floor(totalFrames * 0.25)); 
  const topicsDuration = totalFrames - introDuration;
  const framesPerTopic = Math.max(15, topicsDuration / Math.max(1, topics.length));

  // 1. Main Card Entrance
  const cardProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const cardOpacity = interpolate(cardProgress, [0, 1], [0, 1]);
  const cardY = interpolate(cardProgress, [0, 1], [40, 0]);

  // 2. Main Title Exit (Swipes off before topics start)
  const mainTitleExitProgress = spring({
    frame: frame - introDuration + 10, // Start exit slightly before intro ends for overlap
    fps,
    config: { damping: 14 },
  });
  const mainTitleOpacity = 1 - mainTitleExitProgress;
  const mainTitleX = interpolate(mainTitleExitProgress, [0, 1], [0, -100]); // Swipes out to the left
  const mainTitleBlur = interpolate(mainTitleExitProgress, [0, 1], [0, 10]);

  return (
    <AbsoluteFill style={{ ...bgStyle, fontFamily: interFamily }}>
      {/* Soft Gradient Grid Layer (SVG to strictly avoid CSS mask-image flicker) */}
      {!transparentBackground && (
        <svg width="100%" height="100%" style={{ position: "absolute", top: 0, left: 0 }}>
          <defs>
            <pattern id="soft-grid" width="60" height="60" patternUnits="userSpaceOnUse">
              <path d="M 60 0 L 0 0 0 60" fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="1"/>
            </pattern>
            <radialGradient id="grid-fade" cx="50%" cy="50%" r="60%">
              <stop offset="0%" stopColor="white" stopOpacity="1" />
              <stop offset="100%" stopColor="white" stopOpacity="0" />
            </radialGradient>
            <mask id="grid-mask">
              <rect width="100%" height="100%" fill="url(#grid-fade)" />
            </mask>
          </defs>
          <rect width="100%" height="100%" fill="url(#soft-grid)" mask="url(#grid-mask)" />
        </svg>
      )}

      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: "40px",
          position: "relative",
        }}
      >
        {/* The Card - Apple Glass Style */}
        <div
          style={{
            width: "100%",
            maxWidth: "800px",
            minHeight: "400px",
            backgroundColor: cardColor,
            backdropFilter: "blur(40px) saturate(180%)",
            WebkitBackdropFilter: "blur(40px) saturate(180%)",
            border: "1px solid rgba(255,255,255,0.1)",
            borderTop: "1px solid rgba(255,255,255,0.25)",
            borderLeft: "1px solid rgba(255,255,255,0.15)",
            borderRadius: "32px",
            padding: "64px",
            boxShadow: "0 30px 60px rgba(0,0,0,0.4), inset 0 1px 1px rgba(255,255,255,0.15)",
            transform: `translateY(${cardY}px)`,
            opacity: cardOpacity,
            display: "flex",
            flexDirection: "column",
            position: "relative",
            overflow: "hidden", // Ensures swiping text clips cleanly
          }}
        >
          <div style={{ position: "relative", width: "100%", flex: 1, minHeight: "280px" }}>
            
            {/* Main Title (Intro) */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                opacity: mainTitleOpacity,
                transform: `translateX(${mainTitleX}px)`,
                filter: `blur(${mainTitleBlur}px)`,
              }}
            >
              <h1
                style={{
                  color: textColor,
                  fontSize: "68px",
                  fontWeight: 700,
                  lineHeight: 1.1,
                  letterSpacing: "-2px",
                  margin: 0,
                  textAlign: "center",
                }}
              >
                {mainTitle}
              </h1>
            </div>

            {/* Topics Sequence */}
            {topics.map((topic, i) => {
              const tStart = introDuration + i * framesPerTopic;
              const tExitStart = tStart + framesPerTopic - 15;
              const isLast = i === topics.length - 1;

              const enterProgress = spring({ frame: frame - tStart, fps, config: { damping: 14 } });
              const exitProgress = isLast ? 0 : spring({ frame: frame - tExitStart, fps, config: { damping: 14 } });
              
              const opacity = enterProgress - exitProgress;
              // Enters from right, exits to left
              const translateX = interpolate(enterProgress, [0, 1], [100, 0]) - interpolate(exitProgress, [0, 1], [0, -100]);
              const blur = interpolate(enterProgress, [0, 1], [10, 0]) + interpolate(exitProgress, [0, 1], [0, 10]);

              return (
                <div
                  key={`topic-${i}`}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    opacity,
                    transform: `translateX(${translateX}px)`,
                    filter: `blur(${blur}px)`,
                  }}
                >
                  {/* Top Labels Row */}
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "40px" }}>
                    <span style={{ color: accentColor, fontWeight: 700, fontSize: "16px", letterSpacing: "1.5px", textTransform: "uppercase" }}>
                      Topic {pad(i + 1)}
                    </span>
                    <span style={{ color: subTextColor, fontWeight: 700, fontSize: "16px", letterSpacing: "1px" }}>
                      {pad(i + 1)} / {pad(topics.length)}
                    </span>
                  </div>

                  {/* Main Topic Text */}
                  <h2
                    style={{
                      color: textColor,
                      fontSize: "60px",
                      fontWeight: 700,
                      lineHeight: 1.1,
                      letterSpacing: "-1.5px",
                      margin: 0,
                      textAlign: "left",
                    }}
                  >
                    {topic}
                  </h2>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DashboardCardReveal;